/* @lc app=leetcode id=3327 lang=kotlin */ class Solution { fun hs(h: Array<LongArray>, pw: Array<LongArray>, l: Int, len: Int): Long = ((((h[0][l + len] - h[0][l] * pw[0][len]) % 1_000_000_007L + 1_000_000_007L) % 1_000_000_007L) shl 32) or (((h[1][l + len] - h[1][l] * pw[1][len]) % 998_244_353L + 998_244_353L) % 998_244_353L) fun ph(t: List<Int>): Array<LongArray> = arrayOf(1_000_000_007L to 131L, 998_244_353L to 137L).map { (md, b) -> t.runningFold(0L) { a, c -> (a * b + c) % md }.toLongArray() }.toTypedArray() fun findAnswer(parent: IntArray, s: String): BooleanArray = parent.size.let { n -> parent.indices.drop(1).groupBy { parent[it] }.let { g -> java.util.ArrayDeque<Int>().also { it.addFirst(0) }.let { st -> generateSequence { st.pollFirst() }.onEach { v -> g[v].orEmpty().forEach { st.addFirst(it) } }.toList().reversed().let { post -> IntArray(n).let { pos -> post.forEachIndexed { i, v -> pos[v] = i }.let { IntArray(n) { 1 }.also { sz -> post.forEach { v -> if (v != 0) sz[parent[v]] += sz[v] } }.let { sz -> post.map { s[it].code }.let { t -> ph(t).let { f -> ph(t.reversed()).let { r -> arrayOf(generateSequence(1L) { it * 131 % 1_000_000_007L }.take(n + 1).toList().toLongArray(), generateSequence(1L) { it * 137 % 998_244_353L }.take(n + 1).toList().toLongArray()).let { pw -> BooleanArray(n) { v -> (pos[v] - sz[v] + 1).let { l -> hs(f, pw, l, sz[v]) == hs(r, pw, n - 1 - pos[v], sz[v]) } } } } } } } } } } } } } }